style.css:
@-moz-document domain("chat.deepseek.com") {
/* إعداد الاتجاه العام إلى RTL */
    body, html {
        direction: rtl;
        text-align: right;
    }

    /* ضبط الحاويات الرئيسية إذا كانت موجودة */
    .main-container, .container, #app, .chat-container {
        direction: rtl;
    }

    /* عكس اتجاه حاويات الفليكس إذا كنت تستخدم flexbox */
    .flex-row {
        flex-direction: row-reverse;
    }

    .flex-column {
        flex-direction: column-reverse;
    }

    /* محاذاة حقول الإدخال والأزرار */
    input[type="text"], textarea {
        text-align: right;
    }

    /* ضبط فقاعات الدردشة */
    .chat-bubble {
        float: right;
        /* إذا كانت فقاعات الدردشة تحتوي على هامش أيسر، قم بتبديله إلى اليمين */
        margin-right: 10px;
        margin-left: 0;
    }

    .chat-bubble.user {
        background-color: #dcf8c6; /* لون فقاعات المستخدم كمثال */
    }

    .chat-bubble.bot {
        background-color: #f1f0f0; /* لون فقاعات الروبوت كمثال */
    }

    /* تعديل الشريط الجانبي أو التنقل إذا كان موجودًا */
    .sidebar, .navigation {
        float: right;
    }

    /* ضبط أي أيقونات أو أسهم تشير إلى الاتجاه */
    .arrow-left {
        transform: rotate(180deg);
    }

    /* التأكد من ظهور شريط التمرير على اليسار إذا لزم الأمر */
    ::-webkit-scrollbar {
        width: 12px;
    }

    /* تعديلات إضافية حسب بنية الموقع */
    
    /* مثال: ضبط العناوين */
    h1, h2, h3, h4, h5, h6 {
        text-align: right;
    }

    /* مثال: تعديل الأزرار */
    button {
        float: right;
    }

    /* التعامل مع أي نوافذ حوارية (مودال) */
    .modal {
        direction: rtl;
        text-align: right;
    }

    /* **إضافة قواعد خاصة بكتل الكود لجعلها من اليسار إلى اليمين** */
    /* استهداف عناصر الكود الأساسية */
    code, pre {
        direction: ltr;
        text-align: left;
    }

    /* إذا كانت كتل الكود داخل حاويات معينة، يمكنك إضافة المزيد من المحددات */
    .chat-bubble code, .chat-bubble pre {
        direction: ltr;
        text-align: left;
        /* إضافة بعض التنسيقات لتحسين عرض الكود */
        background-color: #f5f5f5;
        padding: 10px;
        border-radius: 5px;
        overflow-x: auto;
        font-family: Consolas, "Courier New", monospace;
    }
}
